const end = Date.parse('2026-10-21T14:45:30Z');
const got = [];
const done = /^(man|rat|goblin|duck|woman|cow|imp|chicken|giant spider|spider|bear|giant rat|sheep|hans|cook|bob|butterfly|shop keeper|shop assistant)$/i;
let misses = 0;
while (Date.now() < end && misses < 3) {
  const cands = (sdk.getState().nearbyNpcs || []).filter(n => !done.test(n.name) && !n.name.toLowerCase().startsWith('bear'));
  const t = cands[0];
  if (!t) { misses++; await new Promise(r => setTimeout(r, 800)); continue; }
  const r = await bot.attack(t, 15000);
  got.push(`${t.name}:${r.success ? 'ok' : r.reason}`);
  if (!r.success) misses++;
  await new Promise(r => setTimeout(r, 800));
}
return { got: got.slice(-6), now: new Date().toISOString() };
